CREATE TABLE "${primehrSchema}".ld_nomination (
 id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,offering_id VARCHAR(36) NOT NULL,offering_version INTEGER NOT NULL,offering_fingerprint VARCHAR(64) NOT NULL,offering_title VARCHAR(200) NOT NULL,schedule_start TIMESTAMP WITH TIME ZONE NOT NULL,schedule_end TIMESTAMP WITH TIME ZONE NOT NULL,
 source_type VARCHAR(20) NOT NULL,source_id VARCHAR(36),source_version BIGINT,source_fingerprint VARCHAR(64),justification VARCHAR(3000) NOT NULL,
 employee_id BIGINT NOT NULL,employee_no VARCHAR(100) NOT NULL,employee_name VARCHAR(300) NOT NULL,appointment_id BIGINT NOT NULL,employee_fingerprint VARCHAR(64) NOT NULL,business_unit_id BIGINT NOT NULL,business_unit_name VARCHAR(200) NOT NULL,area_id BIGINT,area_name VARCHAR(200),organization_fingerprint VARCHAR(64) NOT NULL,
 estimated_cost NUMERIC(19,2) NOT NULL,initiator_type VARCHAR(20) NOT NULL,initiated_by VARCHAR(100) NOT NULL,status VARCHAR(20) NOT NULL,content_revision INTEGER NOT NULL,submitted_by VARCHAR(100),submitted_at TIMESTAMP WITH TIME ZONE,approved_by VARCHAR(100),approved_at TIMESTAMP WITH TIME ZONE,return_reason VARCHAR(2000),record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,
 CONSTRAINT fk_ld_nomination_offering FOREIGN KEY(offering_id) REFERENCES "${primehrSchema}".ld_offering(id),CONSTRAINT uk_ld_nomination_offering_employee UNIQUE(agency_id,offering_id,employee_id),CONSTRAINT ck_ld_nomination_source CHECK(source_type IN ('IDP_ITEM','PLAN_SOURCE','JUSTIFIED')),CONSTRAINT ck_ld_nomination_initiator CHECK(initiator_type IN ('EMPLOYEE','SUPERVISOR','LD_STAFF')),CONSTRAINT ck_ld_nomination_status CHECK(status IN ('DRAFT','SUBMITTED','RECOMMENDED','RETURNED','APPROVED','CANCELLED')),CONSTRAINT ck_ld_nomination_values CHECK(offering_version>=1 AND schedule_end>schedule_start AND estimated_cost>=0 AND content_revision>=1));
CREATE INDEX ix_ld_nomination_employee ON "${primehrSchema}".ld_nomination(agency_id,employee_no,status);
CREATE INDEX ix_ld_nomination_offering_status ON "${primehrSchema}".ld_nomination(agency_id,offering_id,status);

CREATE TABLE "${primehrSchema}".ld_nomination_route (id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,nomination_id VARCHAR(36) NOT NULL,route_revision INTEGER NOT NULL,request_code VARCHAR(100) NOT NULL,business_unit_id BIGINT NOT NULL,route_fingerprint VARCHAR(64) NOT NULL,submitted_content_revision INTEGER NOT NULL,current_level INTEGER NOT NULL,status VARCHAR(20) NOT NULL,submitted_by VARCHAR(100) NOT NULL,submitted_at TIMESTAMP WITH TIME ZONE NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_ld_nomination_route_nomination FOREIGN KEY(nomination_id) REFERENCES "${primehrSchema}".ld_nomination(id),CONSTRAINT uk_ld_nomination_route_revision UNIQUE(agency_id,nomination_id,route_revision),CONSTRAINT ck_ld_nomination_route_status CHECK(status IN ('ACTIVE','RETURNED','COMPLETED','CANCELLED','SUPERSEDED')),CONSTRAINT ck_ld_nomination_route_values CHECK(route_revision>=1 AND submitted_content_revision>=1 AND current_level>=1));
CREATE INDEX ix_ld_nomination_route_current ON "${primehrSchema}".ld_nomination_route(agency_id,nomination_id,status,route_revision);

CREATE TABLE "${primehrSchema}".ld_nomination_route_step (id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,route_id VARCHAR(36) NOT NULL,route_level INTEGER NOT NULL,action_type VARCHAR(20) NOT NULL,employee_id BIGINT NOT NULL,employee_no VARCHAR(100) NOT NULL,employee_name VARCHAR(300) NOT NULL,appointment_id BIGINT NOT NULL,participant_fingerprint VARCHAR(64) NOT NULL,organization_fingerprint VARCHAR(64) NOT NULL,status VARCHAR(20) NOT NULL,decided_by VARCHAR(100),decided_at TIMESTAMP WITH TIME ZONE,decision_reason VARCHAR(2000),record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_ld_nomination_step_route FOREIGN KEY(route_id) REFERENCES "${primehrSchema}".ld_nomination_route(id),CONSTRAINT uk_ld_nomination_route_step UNIQUE(agency_id,route_id,route_level),CONSTRAINT ck_ld_nomination_step_action CHECK(action_type IN ('RECOMMEND','APPROVE')),CONSTRAINT ck_ld_nomination_step_status CHECK(status IN ('PENDING','CURRENT','RECOMMENDED','RETURNED','APPROVED','SKIPPED')),CONSTRAINT ck_ld_nomination_step_level CHECK(route_level>=1));
CREATE INDEX ix_ld_nomination_step_actor ON "${primehrSchema}".ld_nomination_route_step(agency_id,employee_no,status);

CREATE TABLE "${primehrSchema}".ld_enrollment (id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,nomination_id VARCHAR(36) NOT NULL,offering_id VARCHAR(36) NOT NULL,offering_version INTEGER NOT NULL,offering_fingerprint VARCHAR(64) NOT NULL,employee_id BIGINT NOT NULL,employee_no VARCHAR(100) NOT NULL,employee_name VARCHAR(300) NOT NULL,appointment_id BIGINT NOT NULL,employee_fingerprint VARCHAR(64) NOT NULL,status VARCHAR(20) NOT NULL,confirmed_at TIMESTAMP WITH TIME ZONE,cancelled_at TIMESTAMP WITH TIME ZONE,status_reason VARCHAR(2000),replaces_enrollment_id VARCHAR(36),replaced_by_enrollment_id VARCHAR(36),record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_ld_enrollment_nomination FOREIGN KEY(nomination_id) REFERENCES "${primehrSchema}".ld_nomination(id),CONSTRAINT fk_ld_enrollment_offering FOREIGN KEY(offering_id) REFERENCES "${primehrSchema}".ld_offering(id),CONSTRAINT fk_ld_enrollment_replaces FOREIGN KEY(replaces_enrollment_id) REFERENCES "${primehrSchema}".ld_enrollment(id),CONSTRAINT fk_ld_enrollment_replaced_by FOREIGN KEY(replaced_by_enrollment_id) REFERENCES "${primehrSchema}".ld_enrollment(id),CONSTRAINT uk_ld_enrollment_nomination UNIQUE(agency_id,nomination_id),CONSTRAINT ck_ld_enrollment_status CHECK(status IN ('INVITED','CONFIRMED','DECLINED','CANCELLED','SUBSTITUTED')),CONSTRAINT ck_ld_enrollment_version CHECK(offering_version>=1));
CREATE INDEX ix_ld_enrollment_offering ON "${primehrSchema}".ld_enrollment(agency_id,offering_id,status);
CREATE INDEX ix_ld_enrollment_employee ON "${primehrSchema}".ld_enrollment(agency_id,employee_no,status);

CREATE TABLE "${primehrSchema}".ld_training_order_source (id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,offering_id VARCHAR(36) NOT NULL,offering_version INTEGER NOT NULL,offering_fingerprint VARCHAR(64) NOT NULL,order_number VARCHAR(100) NOT NULL,normalized_order_number VARCHAR(100) NOT NULL,subject VARCHAR(1000) NOT NULL,attendance_directive VARCHAR(3000) NOT NULL,dress_code VARCHAR(1000),notes VARCHAR(2000),approved_by VARCHAR(100) NOT NULL,approved_at TIMESTAMP WITH TIME ZONE NOT NULL,snapshot_fingerprint VARCHAR(64) NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_ld_training_order_offering FOREIGN KEY(offering_id) REFERENCES "${primehrSchema}".ld_offering(id),CONSTRAINT uk_ld_training_order_offering UNIQUE(agency_id,offering_id),CONSTRAINT uk_ld_training_order_number UNIQUE(agency_id,normalized_order_number),CONSTRAINT ck_ld_training_order_version CHECK(offering_version>=1));
CREATE INDEX ix_ld_training_order_approved ON "${primehrSchema}".ld_training_order_source(agency_id,approved_at);

CREATE TABLE "${primehrSchema}".ld_training_order_participant (id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,training_order_id VARCHAR(36) NOT NULL,enrollment_id VARCHAR(36) NOT NULL,enrollment_version BIGINT NOT NULL,enrollment_fingerprint VARCHAR(64) NOT NULL,employee_id BIGINT NOT NULL,employee_no VARCHAR(100) NOT NULL,employee_name VARCHAR(300) NOT NULL,appointment_id BIGINT NOT NULL,employee_fingerprint VARCHAR(64) NOT NULL,enrollment_status VARCHAR(20) NOT NULL,display_order INTEGER NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_ld_training_order_participant_order FOREIGN KEY(training_order_id) REFERENCES "${primehrSchema}".ld_training_order_source(id),CONSTRAINT fk_ld_training_order_participant_enrollment FOREIGN KEY(enrollment_id) REFERENCES "${primehrSchema}".ld_enrollment(id),CONSTRAINT uk_ld_training_order_participant UNIQUE(agency_id,training_order_id,employee_id),CONSTRAINT ck_ld_training_order_participant_status CHECK(enrollment_status='CONFIRMED'),CONSTRAINT ck_ld_training_order_participant_values CHECK(enrollment_version>=0 AND display_order>=1));
CREATE INDEX ix_ld_training_order_participant_order ON "${primehrSchema}".ld_training_order_participant(agency_id,training_order_id,display_order);
